contract InvMutTest is Test {
    C c;
    Attack attacker;

    function setUp() public { c = new C(); }

    // fuzzed params: deposit amount and attacker initial balance
    function testFuzz_property(uint256 depositAmount, uint256 attackerBalance) public {
        // keep values in sensible wide ranges
        depositAmount = bound(depositAmount, 1, 1 ether);
        attackerBalance = bound(attackerBalance, depositAmount, 10 ether);

        // deploy attacker that will re-enter on receive
        attacker = new Attack(address(c));

