        vm.deal(address(attacker), attackerBalance);

        // attacker deposits into C
        vm.prank(address(attacker));
        // call deposit with value depositAmount
        (bool ok,) = address(c).call{value: depositAmount}(abi.encodeWithSignature("deposit()"));
        require(ok);

        // capture contract balance before withdraw
        uint256 before = address(c).balance;

        // attacker calls withdrawAll which in the buggy contract will re-enter and drain twice
        vm.prank(address(attacker));
        // call withdrawAll; attacker will try reentrancy inside its receive
        (bool ok2,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        require(ok2);

        // EXACTLY ONE ASSERT: In the correct contract, after withdrawAll completes the attacker's recorded credit is zero
