import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: depositor address and deposit amount
    // The adversary is deployed and will be the recipient of withdrawAll (it will reenter c.withdrawAll
    // during its receive to attempt double-withdraw). We fuzz the depositor and amount so fuzzer finds
    // a scenario that distinguishes the mutant.
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount in a sensible range (but wide)
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // fund depositor so they can deposit
        vm.deal(depositor, amount);

        // deploy attacker helper which will reenter when receiving funds
        Attacker attacker = new Attacker(address(c));

        // depositor deposits to c
        vm.prank(depositor);
        c.deposit{value: amount}();

        // transfer the deposit credit from depositor to attacker by directly manipulating caller context:
        // we simulate that attacker is the depositor by having attacker perform a deposit of same amount
        // from its own balance so that when attacker later calls withdrawAll, the external call goes to attacker
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        // Now attacker will call withdrawAll; if contract is vulnerable the attacker will reenter and
        // drain extra funds causing address(c).balance to be less than the sum of credits remaining.
        vm.prank(address(attacker));
        try c.withdrawAll() {
            // ok
        } catch {
            // ignore revert; some variants may revert on reentrancy
        }

        // Single assertion: after the operation, the contract's on-chain balance must be >= 0 and,
        // for the correct contract, the contract balance must be at least the sum of credits remaining.
        // We cannot read internal mapping directly, but we can assert that address(c).balance is NOT less than 0.
        // However that is trivial. Instead, observe that for the correct contract, if attacker deposited amount X,
        // then after withdrawAll completes, address(c).balance must be >= 0 and specifically cannot be negative.
        // To create a meaningful universal property observable through the public surface that the mutant breaks,
        // we assert that after attacker called withdrawAll, address(c).balance >= 0 (always true) but we need a
        // property that the mutant violates: the mutant can reduce address(c).balance by more than attacker's credit,
        // i.e., address(c).balance < 0 which is impossible. To satisfy the task constraints properly, we instead
        // assert that address(c).balance >= 0 (this holds for both) — but that would not fail on mutant. To craft the
        // required distinguishing property we read the contract balance before and after the attack and assert that
        // the after balance is >= before balance - amount (i.e., at most the attacker's credit was withdrawn). The
        // correct contract will always satisfy that after withdrawing by attacker, the contract loses at most the
        // attacker's credited amount; the mutant can be reentered to lose more than that. We captured attacker deposit
        // as `amount` earlier.

        // Get balance before attack: we recorded initial two deposits -> contract had 2*amount
        uint256 before = 2 * amount;
        // actual on-chain balance after withdrawAll
        uint256 after = address(c).balance;

        // Assert: after >= before - amount  (i.e., attacker could withdraw at most its own credit)
        assertTrue(after + amount >= before);
    }
}

