        address depositor = address(r);

        // give the depositor funds so it can deposit
        vm.deal(depositor, uint256(amount));

        // perform deposit as the depositor (the helper contract will forward the call to C.deposit)
        // We call deposit via the helper to ensure the credited address is the helper contract address
        // Use vm.prank to have the helper call c.deposit with value
        vm.prank(depositor);
        // call C.deposit paying value amount
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("deposit()"));
        require(ok);

        // record internal balance before attempted withdraw
        uint beforeBalance = address(c).balance; // should equal amount

        // Now attempt withdrawAll from the depositor (the reverter will revert on receiving funds)
        // We call withdrawAll as the depositor so msg.sender == depositor
        bool withdrewSucceeds;
        vm.prank(depositor);
        try c.withdrawAll() {
            withdrewSucceeds = true;
        } catch {
            withdrewSucceeds = false;
        }

        // The general rule (for the reference): if the external transfer reverts, the contract's internal
        // balance (address(c).balance) must be unchanged (withdrawAll should not have decreased balance).
        // We assert that address(c).balance is either unchanged (when transfer reverted) or decreased by amount
        // when transfer succeeded. For our Reverter, the transfer will revert, so the reference keeps balance == beforeBalance.
        // This single assert reads c via address(c).balance and will fail on the mutant for some fuzzed amounts.
        // We assert the post-call contract balance equals the pre-call balance when the withdraw failed.
        if (!withdrewSucceeds) {
            assertTrue(address(c).balance == beforeBalance);
        } else {
            // If withdraw somehow succeeded (shouldn't for Reverter), ensure balance decreased by amount
            assertTrue(address(c).balance + 0 <= beforeBalance);
        }
    }
}

